function prof_build() {
let i = 0;
let n = 0;
let a = 0;
let b = 0;
let v = 0;
let cls = 0;
let q0lon = 0;
let q1lon = 0;
let qlon = 0;
let qlat = 0;
let e = 0;
let total = 0;
let want = 0;
let acc = 0;
let seg = 0;
let dx = 0;
let dy = 0;
cls = fcorner_feat_class(FC_SEL);
n = (SK_W - 8);
if (n > FC_PROF_MAX) n = FC_PROF_MAX;
if (n < 8) n = 8;
PROF_N = n;
PROF_DIRTY = 0;
a = feat_v0(FC_SEL);
b = feat_v1(FC_SEL);
if (FC_PROFMODE == 1 || cls != FC_CLS_COR) {
qlat = fcorner_feat_qlat(FC_SEL);
if (FC_PROFMODE == 1) {
q0lon = 0;
q1lon = FC_SPAN_LON;
} else {
q0lon = fcorner_feat_qlon(FC_SEL) - 1400;
q1lon = fcorner_feat_qlon(FC_SEL) + 1400;
if (q0lon < 0) q0lon = 0;
if (q1lon > FC_SPAN_LON) q1lon = FC_SPAN_LON;
if (q1lon - q0lon < 400) {
q0lon = 0;
q1lon = FC_SPAN_LON;
}
}
for (i = 0; i < n; i = i + 1) {
qlon = q0lon + idiv32((q1lon - q0lon) * i, (n - 1));
PROF_E[i] = fc_elev_q(qlon, qlat);
}
PROF_KM = fc_km_span(q1lon - q0lon, 0);
} else {
total = 0;
for (v = a; v + 1 < b; v = v + 1) {
dx = FC_PT[v * 2 + 2] - FC_PT[v * 2];
dy = FC_PT[v * 2 + 3] - FC_PT[v * 2 + 1];
total = total + fc_km_span(dx, dy);
}
if (total < 1) total = 1;
PROF_KM = total;
for (i = 0; i < n; i = i + 1) {
want = idiv32(total * i, (n - 1));
acc = 0;
qlon = FC_PT[a * 2];
qlat = FC_PT[a * 2 + 1];
for (v = a; v + 1 < b; v = v + 1) {
dx = FC_PT[v * 2 + 2] - FC_PT[v * 2];
dy = FC_PT[v * 2 + 3] - FC_PT[v * 2 + 1];
seg = fc_km_span(dx, dy);
if (acc + seg >= want || v + 2 == b) {
if (seg < 1) seg = 1;
qlon = FC_PT[v * 2] + idiv32(dx * (want - acc), seg);
qlat = FC_PT[v * 2 + 1] + idiv32(dy * (want - acc), seg);
break;
}
acc = acc + seg;
}
PROF_E[i] = fc_elev_q(qlon, qlat);
}
}
PROF_LO = 32000;
PROF_HI = -32000;
for (i = 0; i < n; i = i + 1) {
e = PROF_E[i];
if (e < PROF_LO) PROF_LO = e;
if (e > PROF_HI) PROF_HI = e;
}
if (PROF_HI - PROF_LO < 200) PROF_HI = PROF_LO + 200;
}
